//   backend update = バックエンドの更新 / release = リリース / roll back = ロールバック /
//   one-way update = 単向更新 / preflight = 事前チェック / moved aside = 退避 /
//   usage limit = 使用量制限 / fast mode = 高速モード / credits = クレジット /
//   workflow run = ワークフロー実行（run plan = 実行プラン、step = ステップ）/
//   extra usage directories = 追加ディレクトリ / price table · library · API-equivalent =
//   価格表 · 価格ライブラリ · API 換算額 / capability list = 機能一覧 / up next = 次に届くもの /
